    "wiring_matrix_ref": {
      "type": "string",
      "minLength": 1
    },
    "route_args_verified": {
      "type": "boolean"
    },
    "wrapper_normalization_verified": {
      "type": "boolean"
    },
    "stale_revalidation_verified": {
      "type": "boolean"
    },
    "admissibility_verified": {
      "type": "boolean"
    },
    "correlation_passthrough_verified": {
      "type": "boolean"
    },
